import { Global, Theme, css } from '@emotion/react';
import emotionReset from 'emotion-reset';

import { media } from './theme';

const style = (theme: Theme) => css`
  @import url('https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.6/dist/web/variable/pretendardvariable-dynamic-subset.css');

  ${emotionReset}

  *,
  *::after,
  *::before {
    box-sizing: border-box;
    margin: 0;
    border: 0;
    padding: 0;
  }

  html,
  body,
  #___gatsby,
  #gatsby-focus-wrapper {
    width: 100%;
    height: 100%;
    color: ${theme.colors.text.primary};
    background-color: ${theme.colors.surface.default};
    font-family:
      'Pretendard Variable',
      Pretendard,
      -apple-system,
      BlinkMacSystemFont,
      system-ui,
      Roboto,
      'Helvetica Neue',
      'Segoe UI',
      'Apple SD Gothic Neo',
      'Noto Sans KR',
      'Malgun Gothic',
      'Apple Color Emoji',
      'Segoe UI Emoji',
      'Segoe UI Symbol',
      sans-serif;
    font-size: 62.5%;
    font-weight: 400;

    ${media.mobile} {
      font-size: 55%;
    }
  }

  a {
    text-decoration: none;
    color: inherit;
  }

  input,
  button {
    border: none;
    background-color: transparent;
  }

  a:focus-visible,
  button:focus-visible,
  input:focus-visible,
  textarea:focus-visible,
  select:focus-visible,
  [tabindex]:focus-visible {
    outline: 2px solid ${theme.colors.accent.default};
    outline-offset: 2px;
    border-radius: 2px;
  }

  a:focus:not(:focus-visible),
  button:focus:not(:focus-visible),
  input:focus:not(:focus-visible),
  textarea:focus:not(:focus-visible),
  select:focus:not(:focus-visible) {
    outline: none;
  }

  img {
    -webkit-user-select: none;
    -khtml-user-select: none;
    -moz-user-select: none;
    -o-user-select: none;
    user-select: none;
    -webkit-user-drag: none;
    -khtml-user-drag: none;
    -moz-user-drag: none;
    -o-user-drag: none;
  }

  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-thumb {
    border: 2px solid transparent;
    border-radius: 10px;
    background-clip: padding-box;
    background-color: ${theme.colors.text.secondary};
  }

  ::-webkit-scrollbar-track {
    border-radius: 10px;
    box-shadow: inset 0 0 5px ${theme.colors.text.inverse};
    background-color: ${theme.colors.surface.subtle};
  }

  ::selection {
    background-color: ${theme.colors.accent.default};
    color: ${theme.colors.text.inverse};
  }
`;

const GlobalStyle = function () {
  return <Global styles={style} />;
};

export default GlobalStyle;
